// Direct or transitive for pip rows (issue 1027): pip-compile's "# via" lines,
// unknown without them, and the rules file's direct_files and pinned_pairs.
// Fixtures are written to a temp dir; nothing is cloned or installed.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import crypto from 'crypto';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { analyzePinning, viaOf } from '../plugins/pinning.mjs';
import { applyPipRules, compareVersions, parseVersion, satisfies } from '../pipRules.mjs';
import { initDatabase, saveDependencies, getDependencies, dependantsOfRow } from '../ddbbUtils.mjs';
import { labelOfLockfile, labelsOfLockfiles, parseRulesFile, pipRulesOfRepository, useRepositories } from '../products.mjs';
import { summarizeRelease, unprovenPipFiles } from '../export.mjs';
import { buildQueries } from '../plugins/osv.mjs';

function fixture(files) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'piprules-'));
  for (const [name, content] of Object.entries(files)) {
    fs.mkdirSync(path.dirname(path.join(dir, name)), { recursive: true });
    fs.writeFileSync(path.join(dir, name), content);
  }
  return dir;
}

const quiet = (fn) => {
  const log = console.log;
  console.log = () => {};
  try { return fn(); } finally { console.log = log; }
};

const pipOf = dir => quiet(() => analyzePinning(dir)).find(a => a.ecosystem === 'pip');
const row = (pip, file, name) => pip.entries.find(e => e.lockfile === file && e.name === name);

/* ------------------------------- # via ------------------------------- */

test('pip-compile "# via" blocks say direct or transitive, and who pulled a package in', () => {
  const pip = pipOf(fixture({
    'requirements.txt': [
      '#',
      '# This file is autogenerated by pip-compile with Python 3.12',
      '#',
      'anyio==4.16.0 \\', '    --hash=sha256:aaa',
      '    # via',
      '    #   -c tools/.locked-build-constraints.txt',
      '    #   httpx2',
      'pyinstaller==6.0 \\', '    --hash=sha256:bbb',
      '    # via -r tools/requirements-build.in',
      'myapp-core==1.0',
      '    # via myapp (pyproject.toml)',
      'click==8.1.7  # via black, -r requirements.in',
      'idna==3.7     # via anyio, requests',
      'constrained==1.0',
      '    # via -c constraints.txt',
      'frozen==2.0',
      '# The following packages are considered to be unsafe in a requirements file:',
      'setuptools==69.0.0',
      '    # via',
      '    #   pyinstaller',
    ].join('\n'),
  }));
  const at = name => row(pip, 'requirements.txt', name);
  assert.deepEqual([at('anyio').direct, at('anyio').dependants], [false, ['httpx2']], 'a -c line is a constraint, not a user');
  assert.equal(at('pyinstaller').direct, true, '-r <file>: the app asks for it');
  assert.equal(at('myapp-core').direct, true, 'the project\'s own pyproject.toml');
  assert.deepEqual([at('click').direct, at('click').dependants], [true, ['black']], 'inline, comma-separated');
  assert.deepEqual([at('idna').direct, at('idna').dependants], [false, ['anyio', 'requests']]);
  assert.equal(at('constrained').direct, null, 'only a constraint: nothing says');
  assert.equal(at('frozen').direct, null, 'a comment that is no "via" does not attach');
  assert.deepEqual([at('setuptools').direct, at('setuptools').dependants], [false, ['pyinstaller']]);
  assert.equal(at('click').version, '8.1.7', 'the inline comment is not part of the version');
});

test('viaOf: setup.py and setup.cfg are the project too; no annotation says nothing', () => {
  assert.equal(viaOf(['wallet (setup.py)']).direct, true);
  assert.equal(viaOf(['wallet (setup.cfg)']).direct, true);
  assert.deepEqual(viaOf(null), { direct: null, dependants: null });
  assert.deepEqual(viaOf([]), { direct: null, dependants: null });
});

test('pip rows without "# via" are unknown, not direct: a freeze file and a list kept by hand look the same', () => {
  const pip = pipOf(fixture({
    'requirements.txt': ['requests==2.31.0 --hash=sha256:aaa', 'flask >= 2.0, <3 ; python_version >= "3.8"  # web',
      'trezor[hidapi]>=0.20.1,<0.21', 'git+https://github.com/o/r@0123456789abcdef#egg=lib'].join('\n'),
  }));
  assert.deepEqual(pip.entries.map(e => e.direct), [null, null, null, null]);
  assert.equal(row(pip, 'requirements.txt', 'flask').version, '>=2.0,<3', 'range without spaces, marker or comment');
  assert.equal(row(pip, 'requirements.txt', 'trezor').version, '>=0.20.1,<0.21', 'extras are not part of the range');
});

test('the same version twice in one file is merged, not replaced by the last line', () => {
  const db = initDatabase(':memory:');
  const entry = (fields) => ({ ecosystem: 'pip', lockfile: 'requirements.txt', name: 'cryptography', version: '48.0.1', resolved: '', integrity: '', dev: null, scope: null, tier: 'version-pinned', ...fields });
  const stored = saveDependencies(db, 'app', 'v1', [{ ecosystem: 'pip', entries: [
    entry({ direct: true, dependants: null }),
    entry({ direct: false, dependants: ['pyopenssl'] }),
    entry({ name: 'idna', version: '3.7', direct: false, dependants: ['b'] }),
    entry({ name: 'idna', version: '3.7', direct: null, dependants: ['a'] }),
  ] }]);
  assert.equal(stored, 2);
  const rows = getDependencies(db, 'app', 'v1');
  assert.deepEqual(rows.map(r => [r.name, r.direct, dependantsOfRow(r.dependants)]), [
    ['cryptography', 1, ['pyopenssl']],
    ['idna', null, ['a', 'b']],
  ], 'direct if any line is; unknown before transitive; the dependants of both');
  db.close();
});

/* ------------------------------ PEP 440 ------------------------------ */

test('PEP 440 order and ranges', () => {
  const order = ['1.0.dev0', '1.0a1', '1.0b2', '1.0rc1', '1.0', '1.0.post1', '1.0.1', '1!0.1'];
  for (let i = 1; i < order.length; i++) assert.ok(compareVersions(parseVersion(order[i - 1]), parseVersion(order[i])) < 0, `${order[i - 1]} < ${order[i]}`);
  assert.equal(compareVersions(parseVersion('2.0'), parseVersion('2.0.0')), 0);
  assert.ok(satisfies('2.0.2', '<=2.0.2'));
  assert.ok(!satisfies('2.4.1', '<=2.0.2'));
  assert.ok(satisfies('6.6.2', '<6.7,!=6.6.3'));
  assert.ok(!satisfies('6.6.3', '<6.7,!=6.6.3'));
  assert.ok(satisfies('0.7.99.post15', '>=0.7.99.post15'));
  assert.ok(satisfies('2.2.5', '~=2.2'), '~=2.2 is >=2.2, ==2.*');
  assert.ok(!satisfies('3.0', '~=2.2'));
  assert.ok(satisfies('1.4.2', '==1.4.*'));
  assert.ok(!satisfies('1.5', '==1.4.*'));
  assert.ok(!satisfies('1.7rc1', '<1.7'), '<1.7 does not take its own pre-releases');
  assert.ok(!satisfies('1.7.post1', '>1.7'), '>1.7 does not take its own post-releases');
  assert.ok(satisfies('9.2.2', ''), 'no range: any version');
  assert.ok(!satisfies('1.0', '@ https://x'), 'what it cannot read is outside');
  assert.ok(!satisfies('not-a-version', '>=1'));
});

/* ---------------------------- pinned pairs ---------------------------- */

const SCRIPT = 'for f in a b; do pip install -r src/$f; pip freeze > pinned/$f; done\n';
const sha = text => crypto.createHash('sha256').update(text).digest('hex');
const PROOF = [`https://github.com/o/r/blob/${'a'.repeat(40)}/freeze.sh#L1`];
const rulesWith = (extra) => parseRulesFile(JSON.stringify({
  release: 'v1', rules: [{ files: 'docs/**', belongs_to: 'docs', why: 'x', proof: PROOF }], ...extra,
}), 'github.com/o/r');
const PAIR = (hash = sha(SCRIPT)) => ({ pinned_pairs: [{
  source: 'src/', pinned: 'pinned/', script: 'freeze.sh', script_sha256: [hash], always_direct: ['pip'], why: 'x', proof: PROOF,
}] });

// Electrum's shape (4.8.4): tomli is named in one source file only, and pinned in two.
const ELECTRUM_LIKE = {
  'freeze.sh': SCRIPT,
  'src/requirements-build-base.txt': 'pip\nsetuptools_scm[toml]>=3.4.1\ntomli<=2.0.2\n',
  'pinned/requirements-build-base.txt': 'pip==26.2.2\nsetuptools-scm==9.2.2\ntomli==2.0.2\npackaging==26.2\n',
  'src/requirements-build-android.txt': 'pip\nbuild\n',
  'pinned/requirements-build-android.txt': 'pip==26.2.2\nbuild==1.2.2\ntomli==2.4.1\n',
  'src/requirements-ci.txt': 'pytest\n',
};

test('a pinned pair: named in the source file is direct, only pinned is transitive, per file', () => {
  const dir = fixture(ELECTRUM_LIKE);
  const pip = applyPipRules([pipOf(dir)], rulesWith(PAIR()), dir)[0];
  const base = name => row(pip, 'pinned/requirements-build-base.txt', name)?.direct;
  const android = name => row(pip, 'pinned/requirements-build-android.txt', name)?.direct;
  assert.equal(base('setuptools-scm'), true, 'names fold: setuptools_scm[toml] is setuptools-scm');
  assert.equal(base('tomli'), true);
  assert.equal(base('packaging'), false);
  assert.equal(android('tomli'), false, 'tomli<=2.0.2 in the base file does not make the android file\'s 2.4.1 direct');
  assert.equal(android('build'), true);
  assert.equal(android('pip'), true);
  assert.deepEqual(pip.entries.filter(e => e.lockfile.startsWith('src/requirements-build')).map(e => `${e.lockfile} ${e.name} -> ${e.coveredBy}`).sort(), [
    'src/requirements-build-android.txt build -> pinned/requirements-build-android.txt',
    'src/requirements-build-android.txt pip -> pinned/requirements-build-android.txt',
    'src/requirements-build-base.txt pip -> pinned/requirements-build-base.txt',
    'src/requirements-build-base.txt setuptools_scm -> pinned/requirements-build-base.txt',
    'src/requirements-build-base.txt tomli -> pinned/requirements-build-base.txt',
  ], 'the source rows stay, tagged as their pinned rows (row 1a)');
  assert.equal(row(pip, 'src/requirements-ci.txt', 'pytest').coveredBy, undefined);
  assert.equal(row(pip, 'src/requirements-ci.txt', 'pytest').direct, null, 'a source file with no pinned file stays as it is');
});

test('a pinned pair keeps both rows in the database and counts the package once', () => {
  const dir = fixture(ELECTRUM_LIKE);
  const db = initDatabase(':memory:');
  saveDependencies(db, 'electrum', '4.8.4', applyPipRules([pipOf(dir)], rulesWith(PAIR()), dir));
  const tomli = getDependencies(db, 'electrum', '4.8.4').filter(r => r.name === 'tomli' && r.lockfile.endsWith('build-base.txt'));
  assert.deepEqual(tomli.map(r => [r.lockfile, r.dep_version, r.covered_by]), [
    ['pinned/requirements-build-base.txt', '2.0.2', null],
    ['src/requirements-build-base.txt', '<=2.0.2', 'pinned/requirements-build-base.txt'],
  ]);
  const { dependencies } = summarizeRelease(db, 'electrum', '4.8.4');
  // pinned: pip, setuptools-scm, tomli 2.0.2, packaging, build, tomli 2.4.1; ci: pytest
  assert.equal(dependencies.total, 7, 'each pinned package once, no source row counted');
  assert.equal(dependencies.direct, 4, 'pip, setuptools-scm, tomli 2.0.2, build; pip 26.2.2 is one package in both files');
  assert.ok(!dependencies.lockfiles.includes('src/requirements-build-base.txt'));
  // osv looks up the pinned rows only: a range row is neither a query nor "could not be checked"
  const { queries, skipped } = buildQueries(applyPipRules([pipOf(dir)], rulesWith(PAIR()), dir));
  assert.ok(queries.every(q => /^\d/.test(q.version)), queries.map(q => q.version).join());
  assert.equal(Object.values(skipped).reduce((n, v) => n + v, 0), 1, 'only pytest, which no pinned file pins');
  db.close();
});

test('always_direct: the script installs these itself, for every file', () => {
  const dir = fixture({ ...ELECTRUM_LIKE, 'src/requirements-build-android.txt': 'build\n' });
  const pip = applyPipRules([pipOf(dir)], rulesWith(PAIR()), dir)[0];
  assert.equal(row(pip, 'pinned/requirements-build-android.txt', 'pip').direct, true);
});

test('a source package pinned outside its range leaves both files unknown', () => {
  const dir = fixture({ ...ELECTRUM_LIKE, 'src/requirements-build-base.txt': 'pip\ntomli<2\n' });
  const pip = applyPipRules([pipOf(dir)], rulesWith(PAIR()), dir)[0];
  assert.equal(row(pip, 'pinned/requirements-build-base.txt', 'tomli').direct, null);
  assert.equal(row(pip, 'src/requirements-build-base.txt', 'tomli').direct, null, 'kept: nothing pins it');
  assert.ok(pip.resolutionNotes.some(n => /does not pin tomli<2 .* inside its range/.test(n)));
  assert.equal(row(pip, 'pinned/requirements-build-android.txt', 'build').direct, true, 'the other pair still holds');
});

test('a script nobody reviewed leaves the pairs unknown', () => {
  const dir = fixture(ELECTRUM_LIKE);
  const pip = applyPipRules([pipOf(dir)], rulesWith(PAIR('0'.repeat(64))), dir)[0];
  assert.ok(pip.entries.every(e => e.direct === null));
  assert.ok(pip.resolutionNotes.some(n => /freeze\.sh is not the reviewed version/.test(n)));
  const gone = fixture(ELECTRUM_LIKE);
  fs.rmSync(path.join(gone, 'freeze.sh'));
  assert.ok(applyPipRules([pipOf(gone)], rulesWith(PAIR()), gone)[0].resolutionNotes.some(n => /missing/.test(n)));
});

test('direct_files: every pip row of a file a person proved hand-written is direct', () => {
  const dir = fixture({ 'requirements.txt': 'requests==2.31.0\nflask>=2\n', 'tools/requirements.txt': 'black==24.1\n' });
  const rules = rulesWith({ direct_files: [{ files: 'requirements.txt', why: 'typed by hand', proof: PROOF }] });
  const pip = applyPipRules([pipOf(dir)], rules, dir)[0];
  assert.deepEqual(pip.entries.map(e => [e.lockfile, e.direct]), [['requirements.txt', true], ['requirements.txt', true], ['tools/requirements.txt', null]]);
});

test('Electrum and Bitcoin Safe have their pip rules', () => {
  const electrum = pipRulesOfRepository('https://github.com/spesmilo/electrum');
  assert.equal(electrum.pinnedPairs[0].source, 'contrib/requirements/');
  assert.equal(pipRulesOfRepository('https://github.com/ZeusLN/zeus'), null, 'no pip rules: nothing to apply');
});

/* ------------------------------ the format ------------------------------ */

test('pip rules and labels are rejected for anything the format does not allow', () => {
  const broken = (extra, why) => assert.throws(() => rulesWith(extra), why);
  broken({ direct_files: [] }, /direct_files/);
  broken({ direct_files: [{ files: 'requirements.txt', proof: PROOF }] }, /why/);
  broken({ direct_files: [{ files: 'requirements.txt', why: 'x', proof: ['https://github.com/o/r/blob/v1/a'] }] }, /commit hash/);
  const pair = (change) => { const p = PAIR(); change(p.pinned_pairs[0]); return p; };
  broken(pair(p => { p.source = 'src'; }), /two different folders/);
  broken(pair(p => { p.pinned = p.source; }), /two different folders/);
  broken(pair(p => { p.source = 'src/*/'; }), /two different folders/);
  broken(pair(p => { delete p.script; }), /script/);
  broken(pair(p => { p.script_sha256 = 'abc'; }), /sha256/);
  broken(pair(p => { p.always_direct = 'pip'; }), /always_direct/);
  broken(pair(p => { delete p.proof; }), /proof/);
  assert.throws(() => parseRulesFile(JSON.stringify({ release: 'v1', rules: [{ files: 'a', belongs_to: 'desktop', label: '', why: 'x', proof: PROOF }] }), 'github.com/o/r'), /label/);
  assert.throws(() => parseRulesFile(JSON.stringify({ release: 'v1', rules: [{ files: 'a', belongs_to: 'desktop', label: 'x'.repeat(61), why: 'x', proof: PROOF }] }), 'github.com/o/r'), /label/);
});

test('an advisory gets the label only when every file of its version has one', () => {
  useRepositories([{ appId: 'bitcoin.safe', repoUrl: 'https://github.com/andreasgriffin/bitcoin-safe' }]);
  const mac = 'tools/deterministic-build/requirements-build_mac_x86_64.txt';
  assert.equal(labelOfLockfile(mac, 'bitcoin.safe'), 'macOS Intel build only');
  assert.equal(labelOfLockfile('tools/deterministic-build/requirements-build.txt', 'bitcoin.safe'), null);
  assert.deepEqual(labelsOfLockfiles([mac], 'bitcoin.safe'), ['macOS Intel build only'], 'cryptography 48.0.1');
  assert.equal(labelsOfLockfiles([mac, 'tools/deterministic-build/requirements-build.txt'], 'bitcoin.safe'), undefined, 'a file without the label ships it everywhere');
  assert.equal(labelsOfLockfiles([], 'bitcoin.safe'), undefined);
});

test('the export lists the pip files whose rows nobody has settled', () => {
  assert.deepEqual(unprovenPipFiles([
    { ecosystem: 'pip', lockfile: 'b.txt', direct: null },
    { ecosystem: 'pip', lockfile: 'a.txt', direct: null },
    { ecosystem: 'pip', lockfile: 'a.txt', direct: 1 },
    { ecosystem: 'pip', lockfile: 'c.txt', direct: 0 },
    { ecosystem: 'npm', lockfile: 'package-lock.json', direct: null },
  ]), ['a.txt', 'b.txt']);
});

test('the pinning host step applies the repository\'s pip rules before the rows are stored and checked', async () => {
  const { default: pinning } = await import('../plugins/pinning.mjs');
  const dir = fixture(ELECTRUM_LIKE);
  const results = { pinning: [pipOf(dir)] };
  // Electrum's real rules: these files are not in its folders, so nothing changes
  assert.equal((await pinning.host({ name: 'org.electrum.electrum', version: 'v1', db: null, repoUrl: 'https://github.com/spesmilo/electrum', repoPath: dir, results, saves: [] }))[0].entries.length, results.pinning[0].entries.length);
  const electrum = fixture({
    'contrib/freeze_packages.sh': 'x\n',
    'contrib/requirements/requirements.txt': 'qrcode\n',
    'contrib/deterministic-build/requirements.txt': 'qrcode==8.2\npypng==0.20220715.0\n',
  });
  const back = await pinning.host({ name: 'org.electrum.electrum', version: 'v1', db: null, repoUrl: 'https://github.com/spesmilo/electrum', repoPath: electrum, results: { pinning: [pipOf(electrum)] }, saves: [] });
  assert.ok(back[0].entries.every(e => e.direct === null), 'not the reviewed freeze_packages.sh');
  assert.ok(back[0].resolutionNotes.some(n => /not the reviewed version/.test(n)));
});
